import xml.etree.ElementTree as ET
from fractions import Fraction
from datetime import datetime

D = 'data'
OUT = 'out'

cp = configparser.ConfigParser(); cp.read(os.path.join(D, 'program.ini'))
WH = int(cp['units']['wh_per_tick']); MC = int(cp['units']['millicents_per_cent'])
REG = {k.upper(): v for k, v in cp['region_codes'].items()}
SEG = {k.upper(): v for k, v in cp['segment_codes'].items()}
