def tk(wh):
    return int(Fraction(wh, WH) + Fraction(1, 2)) if Fraction(wh, WH) % 1 != Fraction(1, 2) else (wh // WH) + 1

def ticks(wh):
    f = Fraction(wh, WH)
    fl = f.numerator // f.denominator
    rem = f - fl
    return fl + 1 if rem >= Fraction(1, 2) else fl


events = {e['event_id']: e for e in json.load(open(os.path.join(D, 'events.json')))}
sites = {}
for r in csv.DictReader(open(os.path.join(D, 'sites.csv'), newline='')):
