    seen.add((oid, iv))
    m = int(r['register_multiplier'])
    prof[oid][iv] = (ticks(int(r['relief_wh']) * m), ticks(int(r['recovery_wh']) * m))

targets = {}
for r in csv.DictReader(open(os.path.join(D, 'targets.tsv'), newline=''), delimiter='\t'):
    targets[(r['event_id'], REG[r['region_code']], int(r['interval']))] = (ticks(int(r['target_wh'])), int(r['shortfall_weight']))
ceil = {}
for line in open(os.path.join(D, 'feeder_limits.txt')):
    if line.startswith('#'):
        continue
    ceil[(line[0:10].strip(), REG[line[10:14].strip()], int(line[14:17]))] = (ticks(int(line[17:27])), ticks(int(line[27:37])))
floors = {}
for e in json.load(open(os.path.join(D, 'segment_floors.json')))['floors']:
    floors[(e['event_id'], REG[e['region_code']], SEG[e['segment_code']])] = (ticks(int(e['floor_wh'])), int(e['priority_weight']))
state = {}
for line in open(os.path.join(D, 'site_state.jsonl')):
    o = json.loads(line)
    state[(o['event_id'], o['site_id'])] = o
waiv = {}
for r in csv.DictReader(open(os.path.join(D, 'continuity_waivers.csv'), newline='')):
    waiv[(r['event_id'], r['site_id'])] = r
cards = {}
for c in ET.parse(os.path.join(D, 'rate_cards.xml')).getroot().findall('card'):
    ov = c.find('override')
    cards[(c.get('event'), c.get('site'))] = (int((ov if ov is not None else c.find('base')).text), int(c.find('cap').text))
gw = {}
for r in csv.DictReader(open(os.path.join(D, 'recipient_weights.tsv'), newline=''), delimiter='\t'):
    gw[(r['event_id'], r['site_id'])] = int(r['grant_weight'])
pools = {}
for line in open(os.path.join(D, 'pools.txt')):
    if line.startswith('#'):
        continue
    pools[(line[0:10].strip(), REG[line[10:14].strip()])] = int(line[14:26])
allow = {}
parent = {}
lines = [l.rstrip('\n') for l in open(os.path.join(D, 'site_allowances.tsv')) if not l.startswith('#')][1:]
for l in lines:
    f = l.split('\t')
    allow[f[0]] = int(f[1]); parent[f[0]] = f[2] if len(f) > 2 else ''
root = {}
for s in allow:
    n = s
    while parent.get(n):
        n = parent[n]
    root[s] = n


def label(key):
    st = state.get(key, {})
    if st.get('safety_hold'):
        return 'SAFETY_HOLD'
    if st.get('cooldown'):
        return 'COOLDOWN'
    w = waiv.get(key, {})
    if w.get('routine_certificate_pending') != 'Y':
        return 'CLEAR'
    s = sites[key]
    if (w.get('waiver_status') == 'VALID' and w.get('waiver_signed') == 'Y'
            and s['critical'] == 'Y' and SEG[s['segment_code']] == 'public'):
        return 'CONTINUITY_WAIVED'
    return 'CERTIFICATE_PENDING'


labels = {k: label(k) for k in sites}

# ---- replay selection with full product enumeration ----
season = sorted(events.values(), key=lambda e: (datetime.fromisoformat(e['dispatch_start']), [-ord(c) for c in e['event_id']]))
by_event = collections.defaultdict(list)
for oid, o in offers.items():
    by_event[o['event_id']].append(oid)

consumed = collections.Counter()
selection = {}
tie_counts = {}
for ev in season:
    eid = ev['event_id']; n = ev['interval_count']
    cand = collections.defaultdict(lambda: collections.defaultdict(list))
    for oid in by_event[eid]:
        o = offers[oid]
        key = (eid, o['site_id'])
        if not state.get(key, {}).get('dispatch_authorized'):
            continue
        rt = sum(prof[oid].get(t, (0, 0))[0] for t in range(1, n + 1))
        rr = root[o['site_id']]
        if rt > allow[rr] - consumed[rr]:
            continue
        cand[REG[sites[key]['region_code']]][o['site_id']].append(oid)
    for region in REGIONS:
        groups = [v for k, v in sorted(cand[region].items())]
        tg = [targets.get((eid, region, t), (0, 0)) for t in range(1, n + 1)]
        ce = [ceil.get((eid, region, t), (0, 0)) for t in range(1, n + 1)]
        best = None; bestids = None; cnt = 0
        for combo in itertools.product(*[[None] + g for g in groups]):
            sel = [o for o in combo if o]
            rel = [0] * n; rec = [0] * n; segrel = collections.Counter(); cost = 0
            for oid in sel:
                for t in range(1, n + 1):
                    a, b = prof[oid].get(t, (0, 0))
                    rel[t - 1] += a; rec[t - 1] += b
                segrel[SEG[sites[(eid, offers[oid]['site_id'])]['segment_code']]] += sum(prof[oid].get(t, (0, 0))[0] for t in range(1, n + 1))
                cost += int(offers[oid]['bid_cost_cents'])
            if any(rel[t] > ce[t][0] or rec[t] > ce[t][1] for t in range(n)):
                continue
            sh = sum(tg[t][1] * max(0, tg[t][0] - rel[t]) for t in range(n))
            df = 0
            for s in SEGMENTS:
                f, p = floors.get((eid, region, s), (0, 0))
                df += p * max(0, f - segrel[s])
            bl = ev['objective']['cost_weight'] * cost + ev['objective']['recovery_weight'] * sum(rec)
            ov = sum(max(0, rel[t] - tg[t][0]) for t in range(n))
            k = (sh, df, bl, ov, len(sel))
            ids = tuple(sorted(sel))
            if best is None or k < best:
                best, bestids, cnt = k, ids, 1
            elif k == best:
                cnt += 1
                bestids = max(bestids, ids)
        selection[(eid, region)] = bestids
        tie_counts[(eid, region)] = cnt
        for oid in bestids:
            rr = root[offers[oid]['site_id']]
            consumed[rr] += sum(prof[oid].get(t, (0, 0))[0] for t in range(1, n + 1))

